-- v1.7.4 Service Ladder + Maintenance Task Matrix
CREATE TABLE IF NOT EXISTS "MaintenanceTaskDefinitions" ("Id" uuid PRIMARY KEY,"SectionName" text NOT NULL,"TaskCode" text NOT NULL,"TaskName" text NOT NULL,"ActionCode" text NOT NULL,"Specification" text NOT NULL DEFAULT '',"Severity" text NOT NULL DEFAULT '',"UnitCode" text NOT NULL DEFAULT '',"SuggestedIssueCode" text NOT NULL DEFAULT '',"SortOrder" integer NOT NULL DEFAULT 0,"IsActive" boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MaintenanceTaskDefinitions_TaskCode" ON "MaintenanceTaskDefinitions"("TaskCode");
CREATE TABLE IF NOT EXISTS "MaintenancePlanMatrixItems" ("Id" uuid PRIMARY KEY,"MaintenancePlanId" uuid NOT NULL,"MaintenanceTaskDefinitionId" uuid NOT NULL,"Sequence" integer NOT NULL DEFAULT 0,"IsMandatory" boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MaintenancePlanMatrixItems_Plan_Task" ON "MaintenancePlanMatrixItems"("MaintenancePlanId","MaintenanceTaskDefinitionId");
CREATE TABLE IF NOT EXISTS "MaintenanceReplacementRules" ("Id" uuid PRIMARY KEY,"Platform" text NOT NULL DEFAULT '',"SystemName" text NOT NULL DEFAULT '',"ItemName" text NOT NULL DEFAULT '',"PartNumber" text NOT NULL DEFAULT '',"ActionCode" text NOT NULL DEFAULT 'R',"UsageInterval" numeric NULL,"UsageUnit" text NOT NULL DEFAULT '',"IntervalMonths" integer NULL,"Quantity" numeric NULL,"Notes" text NOT NULL DEFAULT '',"IsActive" boolean NOT NULL DEFAULT true);
